import random
def gen(rng):
    n=rng.randint(1,3); total=rng.randint(1,10)
    sizes=[0]*n
    for _ in range(total):
        sizes[rng.randrange(n)]+=1
    while any(s>4 for s in sizes) or sum(sizes)>10:
        sizes[sizes.index(max(sizes))]-=1
    memlen=rng.randint(1,8)
    widths=[w for w in (1,2,4) if w<=memlen]
    threads=[]
    for s in sizes:
        prog=[]
        for _ in range(s):
            k=rng.choice(['store','load','fence','xchg'])
            w=rng.choice(widths)
            a=rng.randint(0,memlen-w)
            if k=='store': prog.append(['store',a,w,rng.randrange(1<<(8*w))])
            elif k=='load': prog.append(['load',a,w])
            elif k=='fence': prog.append(['fence'])
            else: prog.append(['xchg',a,w,rng.randrange(1<<(8*w))])
        threads.append(prog)
    return {'memory':[rng.randrange(256) for _ in range(memlen)],'threads':threads}
